from confluent_kafka import Producer
import json

p = Producer({"bootstrap.servers": "kafka:9092", "enable.idempotence": True, "acks": "all"})

def laporan(err, msg):
    if err:
        print("gagal kirim:", err)
    else:
        print(f"{msg.key().decode()} -> partisi {msg.partition()} offset {msg.offset()}")

for status in ["dibuat", "dibayar", "dikirim"]:
    p.produce("pesanan", key="INV-7", value=json.dumps({"status": status}), callback=laporan)
p.flush()

